c.solution:
int solve(const int values[], int length) {
  int stack[100], size = 0;
  for (int i = 0; i < length; i++) {
    if (size > 0 && stack[size - 1] == values[i]) size--;
    else stack[size++] = values[i];
  }
  return size;
}
